  3	import com.zaxxer.hikari.HikariConfig;
  4	import com.zaxxer.hikari.HikariDataSource;
  5	import io.javalin.Javalin;
  6	import java.time.Clock;
  7	import shop.domain.Catalog;
  8	import shop.domain.shipping.TransLogClient;
  9	import shop.persistence.postgres.PostgresStore;
 10	import shop.service.Application;
 11	import shop.web.Routes;
 12	
 13	public final class App {
 14	    private App() {
 15	    }
 16	
 17	    public static void main(String[] args) {
 18	        HikariConfig config = new HikariConfig();
 19	        config.setJdbcUrl(System.getenv("DB_URL"));
 20	        config.setUsername(System.getenv("DB_USER"));
 21	        config.setPassword(System.getenv("DB_PASSWORD"));
 22	        config.setMaximumPoolSize(10);
 23	        HikariDataSource dataSource = new HikariDataSource(config);
 24	
 25	        PostgresStore store = new PostgresStore(dataSource);
 26	        store.migrate();
 27	        store.inTransaction(tx -> {
 28	            Catalog.initial().forEach(tx.products()::insertIfAbsent);
 29	            return null;
 30	        });
 31	
 32	        Application services = Application.create(store, new TransLogClient(System.getenv("TRANSLOG_URL")),
 33	                Clock.systemUTC());
 34	        Javalin app = Javalin.create();
 35	        Routes.register(app, services);
 36	        String port = System.getenv("PORT");
 37	        app.start(port == null || port.isBlank() ? 8080 : Integer.parseInt(port));
 38	    }
 39	}
 40	package shop.web;
 41	
 42	import com.fasterxml.jackson.core.JsonProcessingException;
 43	import com.fasterxml.jackson.databind.JsonNode;
 44	import io.javalin.Javalin;
 45	import io.javalin.http.Context;
 46	import java.time.Instant;
 47	import java.util.Map;
 48	import shop.Json;
 49	import shop.domain.DomainException;
 50	import shop.domain.ErrorCode;
 51	import shop.service.Application;
 52	
 53	public final class Routes {
 54	    private Routes() {
 55	    }
 56	
 57	    public static void register(Javalin app, Application services) {
 58	        app.post("/checkout/summary", ctx -> json(ctx, 200,
 59	                services.checkout().summary(CheckoutRequestParser.parse(ctx.body()))));
 60	        app.post("/orders", ctx -> json(ctx, 201,
 61	                services.checkout().register(CheckoutRequestParser.parse(ctx.body()))));
 62	        app.get("/orders/{id}", ctx -> json(ctx, 200, services.orders().get(ctx.pathParam("id"))));
 63	        app.post("/orders/{id}/payment", ctx -> {
 64	            JsonNode body = lenientBody(ctx);
 65	            json(ctx, 200, services.orders().confirmPayment(ctx.pathParam("id"),
 66	                    CheckoutRequestParser.text(body.path("transactionId")), instant(body.path("paidAt"))));
 67	        });
 68	        app.post("/orders/{id}/shipment", ctx -> json(ctx, 200, services.orders().ship(ctx.pathParam("id"),
 69	                CheckoutRequestParser.text(lenientBody(ctx).path("trackingCode")))));
 70	        app.post("/orders/{id}/delivery", ctx -> json(ctx, 200, services.orders().deliver(ctx.pathParam("id"))));
 71	        app.post("/orders/{id}/cancellation", ctx -> json(ctx, 200, services.orders().cancel(ctx.pathParam("id"))));
 72	        app.get("/products/{sku}", ctx -> json(ctx, 200, services.queries().product(ctx.pathParam("sku"))));
 73	        app.get("/customers/{cpf}", ctx -> json(ctx, 200, services.queries().customer(ctx.pathParam("cpf"))));
 74	        app.get("/customers/{cpf}/notifications", ctx -> json(ctx, 200,
 75	                services.queries().notifications(ctx.pathParam("cpf"))));
 76	        app.post("/notifications/{id}/read", ctx -> json(ctx, 200, services.queries().markRead(ctx.pathParam("id"))));
 77	
 78	        app.exception(DomainException.class, (e, ctx) -> json(ctx, e.status(), Map.of("error", e.code().name())));
 79	        app.exception(Exception.class, (e, ctx) -> {
 80	            e.printStackTrace();
 81	            json(ctx, 500, Map.of("error", "INTERNAL_ERROR"));
 82	        });
 83	    }
 84	
 85	    private static void json(Context ctx, int status, Object body) {
 86	        try {
 87	            ctx.status(status).contentType("application/json").result(Json.MAPPER.writeValueAsString(body));
 88	        } catch (JsonProcessingException e) {
 89	            throw new IllegalStateException(e);
 90	        }
 91	    }
 92	
 93	    private static JsonNode lenientBody(Context ctx) {
 94	        try {
 95	            JsonNode node = Json.MAPPER.readTree(ctx.body());
 96	            return node == null ? Json.MAPPER.missingNode() : node;
 97	        } catch (Exception e) {
 98	            return Json.MAPPER.missingNode();
 99	        }
100	    }
101	
102	    private static Instant instant(JsonNode node) {
103	        try {
104	            return node.isTextual() ? Instant.parse(node.asText()) : null;
105	        } catch (Exception e) {
106	            return null;
107	        }
108	    }
109	}
110	package shop.service;
111	
112	import java.time.Duration;
113	import java.time.Instant;
114	import java.util.List;
115	import shop.domain.DomainException;
116	import shop.domain.ErrorCode;
117	import shop.domain.Order;
118	import shop.domain.OrderOperation;
119	import shop.domain.OrderStatus;
120	import shop.persistence.PaymentRepository;
121	import shop.persistence.Store;
122	import shop.persistence.Tx;
123	
124	public class OrderService {
125	    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
126	
127	    private final Store store;
128	    private final List<OrderEventListener> listeners;
129	
130	    public OrderService(Store store, List<OrderEventListener> listeners) {
131	        this.store = store;
132	        this.listeners = listeners;
133	    }
134	
135	    public Order get(String id) {
136	        return store.inTransaction(tx -> tx.orders().find(id).orElseThrow(OrderService::notFound));
137	    }
138	
139	    private record PaymentOutcome(Order order, ErrorCode error) {
140	    }
141	
142	    /** transactionId e paidAt podem ser nulos (ausentes): a ordem das validações é decidida aqui. */
143	    public Order confirmPayment(String id, String transactionId, Instant paidAt) {
144	        PaymentOutcome outcome = store.inTransaction(tx -> {
145	            Order order = tx.orders().findForUpdate(id).orElseThrow(OrderService::notFound);
146	            if (transactionId == null || transactionId.isBlank() || paidAt == null) {
147	                throw new DomainException(ErrorCode.INVALID_ORDER);
148	            }
149	            PaymentRepository.PaymentRecord previous = tx.payments().find(id, transactionId).orElse(null);
150	            if (previous != null) {
151	                return new PaymentOutcome(order, previous.errorCode() == null ? null
152	                        : ErrorCode.valueOf(previous.errorCode()));
153	            }
154	            OrderOperation.PAY.requireAllowed(order.status());
155	            if (Duration.between(order.createdAt(), paidAt).compareTo(PAYMENT_WINDOW) > 0) {
156	                return refuse(tx, order, transactionId, ErrorCode.ORDER_EXPIRED);
157	            }
158	            try {
159	                listeners.forEach(l -> l.onPaid(tx, order));
160	            } catch (StockShortageException e) {
161	                return refuse(tx, order, transactionId, ErrorCode.INSUFFICIENT_STOCK);
162	            }
163	            Order paid = order.withStatus(OrderOperation.PAY.target());
164	            tx.orders().update(paid);
165	            tx.payments().record(id, transactionId, null);
166	            return new PaymentOutcome(paid, null);
167	        });
168	        if (outcome.error() != null) {
169	            throw DomainException.conflict(outcome.error());
170	        }
171	        return outcome.order();
172	    }
173	
174	    private PaymentOutcome refuse(Tx tx, Order order, String transactionId, ErrorCode error) {
175	        cancelOrder(tx, order, false);
176	        tx.payments().record(order.id(), transactionId, error.name());
177	        return new PaymentOutcome(order.withStatus(OrderStatus.CANCELLED), error);
178	    }
179	
180	    public Order ship(String id, String trackingCode) {
181	        return store.inTransaction(tx -> {
182	            Order order = tx.orders().findForUpdate(id).orElseThrow(OrderService::notFound);
183	            if (trackingCode == null || trackingCode.isBlank()) {
184	                throw new DomainException(ErrorCode.INVALID_ORDER);
185	            }
186	            OrderOperation.SHIP.requireAllowed(order.status());
187	            Order shipped = order.withShipment(OrderOperation.SHIP.target(), trackingCode);
188	            tx.orders().update(shipped);
189	            listeners.forEach(l -> l.onShipped(tx, shipped));
190	            return shipped;
191	        });
192	    }
193	
194	    public Order deliver(String id) {
195	        return store.inTransaction(tx -> {
196	            Order order = tx.orders().findForUpdate(id).orElseThrow(OrderService::notFound);
197	            OrderOperation.DELIVER.requireAllowed(order.status());
198	            Order delivered = order.withStatus(OrderOperation.DELIVER.target());
199	            tx.orders().update(delivered);
200	            return delivered;
201	        });
202	    }
203	
204	    public Order cancel(String id) {
205	        return store.inTransaction(tx -> {
206	            Order order = tx.orders().findForUpdate(id).orElseThrow(OrderService::notFound);
207	            OrderOperation.CANCEL.requireAllowed(order.status());
208	            return cancelOrder(tx, order, order.status() == OrderStatus.PAID);
209	        });
210	    }
211	
212	    private Order cancelOrder(Tx tx, Order order, boolean wasPaid) {
213	        Order cancelled = order.withStatus(OrderOperation.CANCEL.target());
214	        tx.orders().update(cancelled);
215	        listeners.forEach(l -> l.onCancelled(tx, cancelled, wasPaid));
216	        return cancelled;
217	    }
218	
219	    private static DomainException notFound() {
220	        return new DomainException(ErrorCode.ORDER_NOT_FOUND);
221	    }
222	}

