312	                    + "&service=" + service);
313	            HttpRequest request = HttpRequest.newBuilder(uri).timeout(TIMEOUT).GET().build();
314	            HttpResponse<String> response = http.send(request, HttpResponse.BodyHandlers.ofString());
315	            if (response.statusCode() != 200) {
316	                throw new CarrierDownException("TransLog status " + response.statusCode(), null);
317	            }
318	            body = Json.MAPPER.readTree(response.body());
319	        } catch (InterruptedException e) {
320	            Thread.currentThread().interrupt();
321	            throw new CarrierDownException("interrupted", e);
322	        } catch (CarrierDownException e) {
323	            throw e;
324	        } catch (Exception e) {
325	            throw new CarrierDownException("TransLog failure", e);
326	        }
