 12	public class PostgresStore implements Store {
 13	    private static final long MIGRATION_LOCK = 727_274L;
 14	
 15	    private static final List<String> SCHEMA = List.of(
 16	            """
 17	            CREATE TABLE IF NOT EXISTS products (
 18	              sku text PRIMARY KEY,
 19	              name text NOT NULL,
 20	              price numeric(12,2) NOT NULL,
 21	              weight_kg numeric(10,3) NOT NULL,
 22	              stock integer NOT NULL CHECK (stock >= 0),
 23	              discontinued boolean NOT NULL)""",
 24	            """
 25	            CREATE TABLE IF NOT EXISTS customers (
 26	              cpf text PRIMARY KEY,
 27	              credit_balance numeric(12,2) NOT NULL DEFAULT 0)""",
 28	            """
 29	            CREATE TABLE IF NOT EXISTS orders (
 30	              id text PRIMARY KEY,
 31	              cpf text NOT NULL REFERENCES customers(cpf),
 32	              status text NOT NULL,
 33	              created_at timestamptz NOT NULL,
 34	              summary_json text NOT NULL,
 35	              items_json text NOT NULL,
 36	              tracking_code text)""",
 37	            "CREATE INDEX IF NOT EXISTS orders_cpf_idx ON orders(cpf)",
 38	            """
 39	            CREATE TABLE IF NOT EXISTS payments (
 40	              order_id text NOT NULL,
 41	              transaction_id text NOT NULL,
 42	              error_code text,
 43	              PRIMARY KEY (order_id, transaction_id))""",
 44	            """
 45	            CREATE TABLE IF NOT EXISTS notifications (
 46	              seq bigserial PRIMARY KEY,
 47	              id text NOT NULL UNIQUE,
 48	              cpf text NOT NULL,
 49	              type text NOT NULL,
 50	              order_id text NOT NULL,
 51	              status text NOT NULL)""",
 52	            "CREATE INDEX IF NOT EXISTS notifications_cpf_idx ON notifications(cpf)");
 53	
 54	    private final DataSource dataSource;
 55	
 56	    public PostgresStore(DataSource dataSource) {
 57	        this.dataSource = dataSource;
 58	    }
 59	
 60	    /** Cria as tabelas; o lock evita corrida quando as duas máquinas sobem juntas. */
 61	    public void migrate() {
 62	        Jdbc.call(() -> {
 63	            try (Connection c = dataSource.getConnection(); Statement s = c.createStatement()) {
 64	                s.execute("SELECT pg_advisory_lock(" + MIGRATION_LOCK + ")");
 65	                try {
 66	                    for (String ddl : SCHEMA) {
 67	                        s.execute(ddl);
 68	                    }
 69	                } finally {
 70	                    s.execute("SELECT pg_advisory_unlock(" + MIGRATION_LOCK + ")");
 71	                }
 72	            }
 73	            return null;
 74	        });
 75	    }
 76	
 77	    @Override
 78	    public <T> T inTransaction(Function<Tx, T> work) {
 79	        try (Connection c = dataSource.getConnection()) {
 80	            c.setAutoCommit(false);
 81	            try {
 82	                T result = work.apply(new PostgresTx(c));
 83	                c.commit();
 84	                return result;
 85	            } catch (RuntimeException | Error e) {
 86	                try {
 87	                    c.rollback();
 88	                } catch (SQLException suppressed) {
 89	                    e.addSuppressed(suppressed);
 90	                }
 91	                throw e;
 92	            }
 93	        } catch (SQLException e) {
 94	            throw new IllegalStateException(e);
 95	        }
 96	    }
 97	}
