 67	
 68	/** Único lugar onde o resumo é calculado: o resumo e o pedido registrado usam o mesmo código. */
 69	public class CheckoutCalculator {
 70	    private static final Pattern ZIP = Pattern.compile("\\d{8}");
 71	
 72	    private final ShippingOptions shippingOptions;
 73	    private final Coupons coupons;
 74	    private final PaymentMethods paymentMethods;
 75	
 76	    public CheckoutCalculator(ShippingOptions shippingOptions, Coupons coupons, PaymentMethods paymentMethods) {
 77	        this.shippingOptions = shippingOptions;
 78	        this.coupons = coupons;
 79	        this.paymentMethods = paymentMethods;
 80	    }
 81	
 82	    /** Valida na ordem definida e devolve o primeiro problema encontrado. */
 83	    public Summary calculate(CheckoutRequest req, Tx tx) {
 84	        List<CartLine> lines = cartLines(req, tx);
 85	        ClubTier tier = ClubTier.parse(req.clubTier());
 86	        Region region = Region.parse(req.region());
 87	        if (req.zipCode() == null || !ZIP.matcher(req.zipCode()).matches()) {
 88	            throw new DomainException(ErrorCode.INVALID_ZIP_CODE);
 89	        }
 90	        ShippingOption shipping = shippingOptions.find(req.shippingMethod())
 91	                .orElseThrow(() -> new DomainException(ErrorCode.INVALID_SHIPPING_METHOD));
 92	
 93	        BigDecimal subtotal = lines.stream().map(CartLine::total).reduce(BigDecimal.ZERO, BigDecimal::add);
 94	        BigDecimal weightKg = lines.stream().map(CartLine::weightKg).reduce(BigDecimal.ZERO, BigDecimal::add);
 95	        ShippingQuote quote = shipping.quote(new ShippingRequest(req.zipCode(), weightKg, region));
 96	        BigDecimal shippingCost = tier.waivesShipping(shipping) ? Money.ZERO : quote.cost();
 97	
 98	        BigDecimal discount = Money.ZERO;
 99	        if (req.coupon() != null) {
100	            Coupon coupon = coupons.find(req.coupon())
