import com.sun.net.httpserver.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

public class Stub {
    static volatile String mode = "ok";
    static volatile String body = "{\"price_cents\":3310,\"eta_hours\":41}";
    static volatile int delayMs = 0;
    static final List<String> log = new CopyOnWriteArrayList<>();

    public static void main(String[] a) throws Exception {
        HttpServer s = HttpServer.create(new InetSocketAddress(9090), 0);
        s.setExecutor(Executors.newCachedThreadPool());
        s.createContext("/admin", ex -> {
            Map<String,String> q = parse(ex.getRequestURI().getRawQuery());
            if (q.containsKey("mode")) mode = q.get("mode");
            if (q.containsKey("body")) body = q.get("body");
            if (q.containsKey("delay")) delayMs = Integer.parseInt(q.get("delay"));
            if (q.containsKey("clear")) log.clear();
            send(ex, 200, "mode=" + mode + " delay=" + delayMs + " body=" + body);
        });
        s.createContext("/log", ex -> send(ex, 200, String.join("\n", log)));
        s.createContext("/v2/quote", ex -> {
            log.add(ex.getRequestURI().toString());
            try { if (delayMs > 0) Thread.sleep(delayMs); } catch (InterruptedException e) {}
            switch (mode) {
                case "500" -> send(ex, 500, "{\"error\":\"boom\"}");
                default -> send(ex, 200, body);
            }
        });
        s.start();
        System.out.println("stub up");
    }
    static Map<String,String> parse(String raw) {
        Map<String,String> m = new HashMap<>();
        if (raw == null) return m;
        for (String p : raw.split("&")) { String[] kv = p.split("=", 2);
            m.put(URLDecoder.decode(kv[0], StandardCharsets.UTF_8), kv.length > 1 ? URLDecoder.decode(kv[1], StandardCharsets.UTF_8) : ""); }
        return m;
    }
    static void send(HttpExchange ex, int code, String b) throws IOException {
        byte[] bytes = b.getBytes(StandardCharsets.UTF_8);
        ex.getResponseHeaders().add("Content-Type", "application/json");
        try { ex.sendResponseHeaders(code, bytes.length); ex.getResponseBody().write(bytes); } catch (IOException e) {}
        ex.close();
    }
}
